insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (68, 4, 24, 28, 'سورة النساء ٢٤ – ٢٨', 'ما أُحلّ من النكاح، و«يريد الله أن يخفف عنكم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 68) = $j$[{"lbl": "الآيتان ٢٤ – ٢٥", "q": "۞وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿٢٤﴾ وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢٥﴾", "w": [["المحصنات", "جمع محصنة، والمراد بها هنا المتزوجة."], ["إلا ما ملكت أيمانكم", "المملوكة بالسبي ونحوه."], ["ما وراء ذلكم", "ما عدا ما حُرّم عليكم."], ["غير مسافحين", "المسافح: الزاني، لأن السفاح هو الزنى."], ["أجورهن فريضة", "مهورهن فريضة."], ["طَوْلاً", "سعة وقدرة على المهر."], ["المحصنات", "في الآية الثانية: العفيفات الحرائر."], ["ولا متخذات أخدان", "الخدين: الخليل الذي يفجر بالمرأة سراً تحت شعار الصداقة."], ["فإذا أُحصنّ", "بأن أسلمن أو تزوّجن، إذ الإحصان يكون بهما."], ["العنت", "الضرر في الدين والبدن."]], "m": "ما زال السياق في بيان ما يحرم من النكاح وما يجوز، فعطف الله على المحرمات بالمصاهرة المرأة المتزوجة، فلا يحل نكاحها إلا بعد مفارقة الزوج بطلاق أو وفاة وانقضاء العدة، واستثنى المملوكة بالسبي في الجهاد الشرعي، إذ انقطعت صلتها بدار الحرب وزوجها، فأذن في نكاحها لمن ملكها بعد أن تُسلم وتُستبرأ بحيضة. «كتاب الله عليكم»: ما حرّمه من المناكح فرضٌ لا يجوز التهاون به. وأحلّ ما وراء ذلك، بشرط ألا يزيد على أربع، أن تطلبوا بأموالكم الزواج محصنين غير مسافحين، بأن يتمّ النكاح بشروطه من الولي والصداق والصيغة والشهود، وإلا فهو السفاح. فمن تزوّج امرأة ودخل بها وجب لها المهر كاملاً، ولا حرج عليهما فيما تراضيا به بعد ذلك، كأن تُسقط من مهرها أو تؤجّله أو تهبه. ثم رخّص لمن لم يستطع نكاح الحرائر لقلة ماله، مع خوفه العنت، أن يتزوّج من الإماء المؤمنات، بإذن أهلهن، وأن يؤتيهن مهورهن، محصنات غير مسافحات علناً ولا متخذات أخدان سراً، «بعضكم من بعض» تطييباً لنفس المؤمن، فإن الإيمان أذهب الفوارق. فإن زنت الأمة بعد إحصانها فعليها نصف ما على الحرة من الجلد، أما الرجم فلا يتنصّف. ثم قال: «وأن تصبروا خير لكم»، أي الصبر على العزوبة خير من نكاح الإماء، والله غفور رحيم.", "h": ["تحريم المرأة المتزوجة حتى يفارقها زوجها بطلاق أو موت، وحتى تنقضي عدتها.", "جواز نكاح المملوكة باليمين وإن كان زوجها حياً في دار الحرب إذا أسلمت؛ لأن الإسلام فصل بينهما.", "وجوب المهور، وجواز إعطاء المرأة من مهرها لزوجها شيئاً.", "جواز التزوّج من المملوكات لمن خاف العنت وهو عادم للقدرة على الزواج من الحرائر.", "وجوب إقامة الحد على من زنت من الإماء إن أُحصنّ بالزواج والإسلام.", "الصبر على العزوبة خير من الزواج بالإماء، لإرشاد الله تعالى إلى ذلك."], "k": "«وأن تصبروا خير لكم»… في أي رغبة أحتاج أن أصبر حتى يأتي الحلال الأكمل؟"}, {"lbl": "الآيات ٢٦ – ٢٨", "q": "يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٢٦﴾ وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا ﴿٢٧﴾ يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا ﴿٢٨﴾", "w": [["يريد الله ليبيّن لكم", "يريد أن يبيّن لكم بما حرّم عليكم وأحلّ لكم ما يكمّلكم ويسعدكم في دنياكم وأخراكم."], ["سنن الذين من قبلكم", "طرائق من قبلكم من الأنبياء والصالحين لتنهجوا نهجهم فتطهروا وتكملوا وتفلحوا مثلهم."], ["ويتوب عليكم", "يرجع بكم عما كنتم عليه من ضلال الجاهلية إلى هداية الإسلام."], ["الذين يتبعون الشهوات", "من اليهود والنصارى والمجوس والزناة."], ["أن تميلوا ميلاً عظيماً", "تحيدوا عن طريق الطهر والصفاء إلى طريق الخبث بارتكاب المحرمات فتبتعدوا عن الرشد بعداً."], ["وخُلق الإنسان ضعيفاً", "لا يصبر عن النساء، فلذا رخّص لهم في الزواج من الفتيات المؤمنات."]], "m": "لما حرّم الله ما حرّم من المناكح وأباح ما أباح، علّل ذلك: يريد الله بما شرع ليبيّن لكم النافع من الضار فتأخذوا النافع وتتركوا الضار، ويهديكم طرائق الصالحين من قبلكم لتسلكوها فتكملوا وتسعدوا في الحياتين، ويتوب عليكم فيرجع بكم من ضلال الجاهلية إلى هداية الإسلام، والله عليم حكيم. والله يريد أن يرجع بكم من حياة الخبث إلى حياة الطهر في ظل تشريع عادل رحيم، ويريد الذين يتبعون الشهوات من الزناة وسائر المنحرفين أن تنحرفوا مثلهم فتنغمسوا في الملاذ والشهوات حتى تصيروا مثلهم لا فضل لكم عليهم. ثم أخبر أنه بإباحته للعاجزين نكاح الفتيات المؤمنات يريد التخفيف والتيسير، رحمة بهم لما يعلم من ضعف الإنسان وعدم صبره عن النساء بما غُرز فيه من الميل إلى أنثاه لحفظ النوع ولحكم عالية.", "h": ["منّة الله تعالى علينا في تعليله الأحكام لنا، لتطمئن نفوسنا ويأتي العمل بانشراح صدر.", "منّة الله تعالى على المؤمنين بهدايتهم إلى طرق الصالحين وسبيل المفلحين ممن كانوا قبلهم.", "منّته تعالى في تطهير المؤمنين من الأخباث وضلال الجاهليات.", "الكشف عن نفسية الإنسان؛ فكل منغمس في خبث أو شر أو فساد يودّ أن يكون كل الناس مثله، كما أن الطاهر الصالح يودّ أن يطهر ويصلح كل الناس.", "ضعف الإنسان أمام غرائزه، لا سيما غريزة الجنس."], "k": "«ويريد الذين يتبعون الشهوات أن تميلوا»… من حولي يشدّني إلى الطهر، ومن يشدّني إلى الميل؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 68;
insert into public.tdb_cards(topic, i, body) select 68, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٤ – ٢٥", "q": "۞وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ﴿٢٤﴾ وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٢٥﴾", "w": [["المحصنات", "جمع محصنة، والمراد بها هنا المتزوجة."], ["إلا ما ملكت أيمانكم", "المملوكة بالسبي ونحوه."], ["ما وراء ذلكم", "ما عدا ما حُرّم عليكم."], ["غير مسافحين", "المسافح: الزاني، لأن السفاح هو الزنى."], ["أجورهن فريضة", "مهورهن فريضة."], ["طَوْلاً", "سعة وقدرة على المهر."], ["المحصنات", "في الآية الثانية: العفيفات الحرائر."], ["ولا متخذات أخدان", "الخدين: الخليل الذي يفجر بالمرأة سراً تحت شعار الصداقة."], ["فإذا أُحصنّ", "بأن أسلمن أو تزوّجن، إذ الإحصان يكون بهما."], ["العنت", "الضرر في الدين والبدن."]], "m": "ما زال السياق في بيان ما يحرم من النكاح وما يجوز، فعطف الله على المحرمات بالمصاهرة المرأة المتزوجة، فلا يحل نكاحها إلا بعد مفارقة الزوج بطلاق أو وفاة وانقضاء العدة، واستثنى المملوكة بالسبي في الجهاد الشرعي، إذ انقطعت صلتها بدار الحرب وزوجها، فأذن في نكاحها لمن ملكها بعد أن تُسلم وتُستبرأ بحيضة. «كتاب الله عليكم»: ما حرّمه من المناكح فرضٌ لا يجوز التهاون به. وأحلّ ما وراء ذلك، بشرط ألا يزيد على أربع، أن تطلبوا بأموالكم الزواج محصنين غير مسافحين، بأن يتمّ النكاح بشروطه من الولي والصداق والصيغة والشهود، وإلا فهو السفاح. فمن تزوّج امرأة ودخل بها وجب لها المهر كاملاً، ولا حرج عليهما فيما تراضيا به بعد ذلك، كأن تُسقط من مهرها أو تؤجّله أو تهبه. ثم رخّص لمن لم يستطع نكاح الحرائر لقلة ماله، مع خوفه العنت، أن يتزوّج من الإماء المؤمنات، بإذن أهلهن، وأن يؤتيهن مهورهن، محصنات غير مسافحات علناً ولا متخذات أخدان سراً، «بعضكم من بعض» تطييباً لنفس المؤمن، فإن الإيمان أذهب الفوارق. فإن زنت الأمة بعد إحصانها فعليها نصف ما على الحرة من الجلد، أما الرجم فلا يتنصّف. ثم قال: «وأن تصبروا خير لكم»، أي الصبر على العزوبة خير من نكاح الإماء، والله غفور رحيم.", "h": ["تحريم المرأة المتزوجة حتى يفارقها زوجها بطلاق أو موت، وحتى تنقضي عدتها.", "جواز نكاح المملوكة باليمين وإن كان زوجها حياً في دار الحرب إذا أسلمت؛ لأن الإسلام فصل بينهما.", "وجوب المهور، وجواز إعطاء المرأة من مهرها لزوجها شيئاً.", "جواز التزوّج من المملوكات لمن خاف العنت وهو عادم للقدرة على الزواج من الحرائر.", "وجوب إقامة الحد على من زنت من الإماء إن أُحصنّ بالزواج والإسلام.", "الصبر على العزوبة خير من الزواج بالإماء، لإرشاد الله تعالى إلى ذلك."], "k": "«وأن تصبروا خير لكم»… في أي رغبة أحتاج أن أصبر حتى يأتي الحلال الأكمل؟"}, {"lbl": "الآيات ٢٦ – ٢٨", "q": "يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٢٦﴾ وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا ﴿٢٧﴾ يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا ﴿٢٨﴾", "w": [["يريد الله ليبيّن لكم", "يريد أن يبيّن لكم بما حرّم عليكم وأحلّ لكم ما يكمّلكم ويسعدكم في دنياكم وأخراكم."], ["سنن الذين من قبلكم", "طرائق من قبلكم من الأنبياء والصالحين لتنهجوا نهجهم فتطهروا وتكملوا وتفلحوا مثلهم."], ["ويتوب عليكم", "يرجع بكم عما كنتم عليه من ضلال الجاهلية إلى هداية الإسلام."], ["الذين يتبعون الشهوات", "من اليهود والنصارى والمجوس والزناة."], ["أن تميلوا ميلاً عظيماً", "تحيدوا عن طريق الطهر والصفاء إلى طريق الخبث بارتكاب المحرمات فتبتعدوا عن الرشد بعداً."], ["وخُلق الإنسان ضعيفاً", "لا يصبر عن النساء، فلذا رخّص لهم في الزواج من الفتيات المؤمنات."]], "m": "لما حرّم الله ما حرّم من المناكح وأباح ما أباح، علّل ذلك: يريد الله بما شرع ليبيّن لكم النافع من الضار فتأخذوا النافع وتتركوا الضار، ويهديكم طرائق الصالحين من قبلكم لتسلكوها فتكملوا وتسعدوا في الحياتين، ويتوب عليكم فيرجع بكم من ضلال الجاهلية إلى هداية الإسلام، والله عليم حكيم. والله يريد أن يرجع بكم من حياة الخبث إلى حياة الطهر في ظل تشريع عادل رحيم، ويريد الذين يتبعون الشهوات من الزناة وسائر المنحرفين أن تنحرفوا مثلهم فتنغمسوا في الملاذ والشهوات حتى تصيروا مثلهم لا فضل لكم عليهم. ثم أخبر أنه بإباحته للعاجزين نكاح الفتيات المؤمنات يريد التخفيف والتيسير، رحمة بهم لما يعلم من ضعف الإنسان وعدم صبره عن النساء بما غُرز فيه من الميل إلى أنثاه لحفظ النوع ولحكم عالية.", "h": ["منّة الله تعالى علينا في تعليله الأحكام لنا، لتطمئن نفوسنا ويأتي العمل بانشراح صدر.", "منّة الله تعالى على المؤمنين بهدايتهم إلى طرق الصالحين وسبيل المفلحين ممن كانوا قبلهم.", "منّته تعالى في تطهير المؤمنين من الأخباث وضلال الجاهليات.", "الكشف عن نفسية الإنسان؛ فكل منغمس في خبث أو شر أو فساد يودّ أن يكون كل الناس مثله، كما أن الطاهر الصالح يودّ أن يطهر ويصلح كل الناس.", "ضعف الإنسان أمام غرائزه، لا سيما غريزة الجنس."], "k": "«ويريد الذين يتبعون الشهوات أن تميلوا»… من حولي يشدّني إلى الطهر، ومن يشدّني إلى الميل؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (69, 4, 29, 33, 'سورة النساء ٢٩ – ٣٣', 'لا تأكلوا أموالكم بالباطل، واجتناب الكبائر، ولا تتمنّوا', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 69) = $j$[{"lbl": "الآيتان ٢٩ – ٣٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا ﴿٢٩﴾ وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا ﴿٣٠﴾", "w": [["آمنوا", "صدّقوا الله والرسول."], ["بالباطل", "بغير حق يبيح أكلها."], ["تجارة", "بيعاً وشراءً، فيحل لصاحب البضاعة أخذ النقود، ولصاحب النقود أخذ البضاعة، إذ لا باطل."], ["تقتلوا أنفسكم", "تزهقوا أرواح بعضكم بعضاً."], ["عدواناً وظلماً", "اعتداءً يكون فيه ظالماً."], ["نصليه ناراً", "ندخله نار جهنم يحترق فيها."]], "m": "ما زال السياق في بيان ما يحل وما يحرم من الأموال والأعراض والأنفس؛ فنادى الله المؤمنين ونهاهم عن أكل أموالهم بينهم بالباطل، بالسرقة أو الغش أو القمار أو الربا وسائر وجوه التحريم، أي بغير عوض مباح أو طيب نفس، واستثنى ما كان عن تجارة قائمة على التراضي بين المتبايعين، لحديث: «إنما البيع عن تراض»، و«البيّعان بالخيار ما لم يتفرّقا». وحرّم قتل المؤمنين بعضهم بعضاً: «ولا تقتلوا أنفسكم»، والنهي يشمل قتل الإنسان نفسه وقتله أخاه المسلم؛ لأن المسلمين كجسم واحد، فمن قتل مسلماً فكأنما قتل نفسه، وعلّل ذلك برحمته بهم. ثم توعّد من يقتل مؤمناً عدواناً وظلماً، أي بالعمد والإصرار والظلم المحض، بأن يُصليه ناراً، وكان ذلك على الله يسيراً لكمال قدرته.", "h": ["حرمة مال المسلم، وكل مال حرام، سواء حازه بسرقة أو غش أو قمار أو ربا.", "إباحة التجارة والترغيب فيها، والرد على من يمنعون الكسب بحجة التوكل.", "تقرير مبدأ «إنما البيع عن تراض»، و«البيّعان بالخيار ما لم يتفرّقا».", "حرمة قتل المسلم نفسه أو غيره من المسلمين؛ لأنهم أمة واحدة.", "الوعيد الشديد لقاتل النفس عدواناً وظلماً بالإصلاء بالنار.", "إن كان القتل غير عدوان بأن كان خطأ، أو غير ظلم بأن كان بحق كالقصاص، فلا يستوجب هذا الوعيد الشديد."], "k": "هل في مكسبي شيء دخل بغير طيب نفس من صاحبه، ولو قليلاً؟"}, {"lbl": "الآية ٣١", "q": "إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا ﴿٣١﴾", "w": [["أن تجتنبوا", "تبتعدوا، لأن الاجتناب ترك الشيء جانباً بعيداً عنه لا يُقبل عليه."], ["كبائر ما تُنهون عنه", "الكبائر ضد الصغائر، والكبيرة تُعرف بالحدّ لا بالعدّ: ما توعّد الله ورسوله عليها، أو لعن فاعلها، أو شرع لها حدّاً يقام على صاحبها."], ["نكفّر", "نغطّي ونستر، فلا نطالب بها ولا نؤاخذ عليها."], ["مدخلاً كريماً", "الجنة دار المتقين."]], "m": "يتفضّل الجبار جلّ جلاله فيمنّ على المؤمنين من هذه الأمة بأن وعدها وعد الصدق: من اجتنب منها كبائر الذنوب، مما نهى الله عنه ورسوله، كفّر عنه صغائرها وأدخله الجنة دار السلام، وخلع عليه حلل الرضوان: «إن تجتنبوا كبائر ما تنهون عنه نكفّر عنكم سيئاتكم وندخلكم مدخلاً كريماً»؛ ولهذا كانت هذه الآية من مبشّرات القرآن لهذه الأمة.", "h": ["وجوب الابتعاد عن سائر الكبائر، والصبر على ذلك حتى الموت.", "الذنوب قسمان: كبائر وصغائر، ولذا وجب العلم بها لاجتناب كبائرها وصغائرها ما أمكن، ومن زلّ فليتب، فإن التائب من الذنب كمن لا ذنب له.", "الجنة لا يدخلها إلا ذوو النفوس الزكية الطاهرة باجتنابهم المدنّسات لها من كبائر الذنوب والآثام والفواحش."], "k": "هل أعرف الكبائر معرفةً تحميني منها؟ وأيّها أحتاج أن أبتعد عن طرقها؟"}, {"lbl": "الآيتان ٣٢ – ٣٣", "q": "وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٣٢﴾ وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا ﴿٣٣﴾", "w": [["ولا تتمنّوا", "التمني: التشهّي والرغبة في حصول الشيء، فإن كان مع زوال المرغوب فيه عن شخص ليحصل للمتمني فهو الحسد."], ["ما فضّل الله به بعضكم", "ما فضّل الله به أحداً منكم فأعطاه علماً أو مالاً أو جاهاً أو سلطاناً."], ["نصيب مما اكتسبوا", "حصة وحظ من الثواب والعقاب بحسب الطاعة والمعصية."], ["موالي", "من يلون التركة ويرثون الميت من أقارب."], ["عقدت أيمانكم", "حالفتموهم وتآخيتم معهم، مؤكدين ذلك بالمصافحة واليمين."], ["فآتوهم نصيبهم", "من الرفادة والوصية والنصرة، لأنهم ليسوا ورثة."]], "m": "قالت أم سلمة رضي الله عنها: ليتنا كنا رجالاً فجاهدنا وكان لنا مثل أجر الرجال، والذين يتمنون، حسداً وغير حسد، كثير؛ فنهى الله المؤمنين عن تمنّي ما فضّل به بعضهم على بعض، فأعطى هذا وحرم ذاك لحِكم، أظهرها الابتلاء بالشكر والصبر. وأخبر أن سنته في الثواب والعقاب الكسب والعمل، فمن أراد الأجر فليعمل بموجباته من الإيمان والعمل الصالح ولا يتمنّاه تمنّياً، ومن خاف العذاب فليكفّ عن الشرك والمعاصي، ومن أراد المال والجاه فليعمل له بسننه، فإن التمنّي بضائع الحمقى: «للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن». ثم بيّن سنّة أخرى في حصول المرغوب، وهي الدعاء: «واسألوا الله من فضله»، فمن سأل ربه وألحّ عليه موقناً بالإجابة أعطاه، فيوفّقه للأسباب ويصرف عنه الموانع، ويعطيه بغير سبب إن شاء. ثم قرّر أن لكلٍّ من الرجال والنساء ورثة يرثونه، أما الموالي بالحلف أو الإخاء فلهم النصرة والرفادة والوصية، إذ لا حظّ لهم في الإرث، والله على كل شيء شهيد، فاتقوه وأطيعوه.", "h": ["قبح التمني وترك العمل.", "حرمة الحسد.", "فضل الدعاء، وأنه من الأسباب التي يحصل بها المراد.", "تقرير مبدأ التوارث في الإسلام.", "من عاقد أحداً على حلف أو آخى أحداً وجب عليه أن يعطيه حق النصرة والمساعدة، وله أن يوصي له بما دون الثلث، أما الإرث فلا حق له فيه لنسخ ذلك.", "وجوب مراقبة الله تعالى؛ لأنه بكل شيء عليم، وعلى كل شيء شهيد."], "k": "ما الذي أتمنّاه مما عند غيري؟ وهل أستبدله اليوم بعمل ودعاء: «واسألوا الله من فضله»؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 69;
insert into public.tdb_cards(topic, i, body) select 69, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٩ – ٣٠", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا ﴿٢٩﴾ وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا ﴿٣٠﴾", "w": [["آمنوا", "صدّقوا الله والرسول."], ["بالباطل", "بغير حق يبيح أكلها."], ["تجارة", "بيعاً وشراءً، فيحل لصاحب البضاعة أخذ النقود، ولصاحب النقود أخذ البضاعة، إذ لا باطل."], ["تقتلوا أنفسكم", "تزهقوا أرواح بعضكم بعضاً."], ["عدواناً وظلماً", "اعتداءً يكون فيه ظالماً."], ["نصليه ناراً", "ندخله نار جهنم يحترق فيها."]], "m": "ما زال السياق في بيان ما يحل وما يحرم من الأموال والأعراض والأنفس؛ فنادى الله المؤمنين ونهاهم عن أكل أموالهم بينهم بالباطل، بالسرقة أو الغش أو القمار أو الربا وسائر وجوه التحريم، أي بغير عوض مباح أو طيب نفس، واستثنى ما كان عن تجارة قائمة على التراضي بين المتبايعين، لحديث: «إنما البيع عن تراض»، و«البيّعان بالخيار ما لم يتفرّقا». وحرّم قتل المؤمنين بعضهم بعضاً: «ولا تقتلوا أنفسكم»، والنهي يشمل قتل الإنسان نفسه وقتله أخاه المسلم؛ لأن المسلمين كجسم واحد، فمن قتل مسلماً فكأنما قتل نفسه، وعلّل ذلك برحمته بهم. ثم توعّد من يقتل مؤمناً عدواناً وظلماً، أي بالعمد والإصرار والظلم المحض، بأن يُصليه ناراً، وكان ذلك على الله يسيراً لكمال قدرته.", "h": ["حرمة مال المسلم، وكل مال حرام، سواء حازه بسرقة أو غش أو قمار أو ربا.", "إباحة التجارة والترغيب فيها، والرد على من يمنعون الكسب بحجة التوكل.", "تقرير مبدأ «إنما البيع عن تراض»، و«البيّعان بالخيار ما لم يتفرّقا».", "حرمة قتل المسلم نفسه أو غيره من المسلمين؛ لأنهم أمة واحدة.", "الوعيد الشديد لقاتل النفس عدواناً وظلماً بالإصلاء بالنار.", "إن كان القتل غير عدوان بأن كان خطأ، أو غير ظلم بأن كان بحق كالقصاص، فلا يستوجب هذا الوعيد الشديد."], "k": "هل في مكسبي شيء دخل بغير طيب نفس من صاحبه، ولو قليلاً؟"}, {"lbl": "الآية ٣١", "q": "إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا ﴿٣١﴾", "w": [["أن تجتنبوا", "تبتعدوا، لأن الاجتناب ترك الشيء جانباً بعيداً عنه لا يُقبل عليه."], ["كبائر ما تُنهون عنه", "الكبائر ضد الصغائر، والكبيرة تُعرف بالحدّ لا بالعدّ: ما توعّد الله ورسوله عليها، أو لعن فاعلها، أو شرع لها حدّاً يقام على صاحبها."], ["نكفّر", "نغطّي ونستر، فلا نطالب بها ولا نؤاخذ عليها."], ["مدخلاً كريماً", "الجنة دار المتقين."]], "m": "يتفضّل الجبار جلّ جلاله فيمنّ على المؤمنين من هذه الأمة بأن وعدها وعد الصدق: من اجتنب منها كبائر الذنوب، مما نهى الله عنه ورسوله، كفّر عنه صغائرها وأدخله الجنة دار السلام، وخلع عليه حلل الرضوان: «إن تجتنبوا كبائر ما تنهون عنه نكفّر عنكم سيئاتكم وندخلكم مدخلاً كريماً»؛ ولهذا كانت هذه الآية من مبشّرات القرآن لهذه الأمة.", "h": ["وجوب الابتعاد عن سائر الكبائر، والصبر على ذلك حتى الموت.", "الذنوب قسمان: كبائر وصغائر، ولذا وجب العلم بها لاجتناب كبائرها وصغائرها ما أمكن، ومن زلّ فليتب، فإن التائب من الذنب كمن لا ذنب له.", "الجنة لا يدخلها إلا ذوو النفوس الزكية الطاهرة باجتنابهم المدنّسات لها من كبائر الذنوب والآثام والفواحش."], "k": "هل أعرف الكبائر معرفةً تحميني منها؟ وأيّها أحتاج أن أبتعد عن طرقها؟"}, {"lbl": "الآيتان ٣٢ – ٣٣", "q": "وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٣٢﴾ وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا ﴿٣٣﴾", "w": [["ولا تتمنّوا", "التمني: التشهّي والرغبة في حصول الشيء، فإن كان مع زوال المرغوب فيه عن شخص ليحصل للمتمني فهو الحسد."], ["ما فضّل الله به بعضكم", "ما فضّل الله به أحداً منكم فأعطاه علماً أو مالاً أو جاهاً أو سلطاناً."], ["نصيب مما اكتسبوا", "حصة وحظ من الثواب والعقاب بحسب الطاعة والمعصية."], ["موالي", "من يلون التركة ويرثون الميت من أقارب."], ["عقدت أيمانكم", "حالفتموهم وتآخيتم معهم، مؤكدين ذلك بالمصافحة واليمين."], ["فآتوهم نصيبهم", "من الرفادة والوصية والنصرة، لأنهم ليسوا ورثة."]], "m": "قالت أم سلمة رضي الله عنها: ليتنا كنا رجالاً فجاهدنا وكان لنا مثل أجر الرجال، والذين يتمنون، حسداً وغير حسد، كثير؛ فنهى الله المؤمنين عن تمنّي ما فضّل به بعضهم على بعض، فأعطى هذا وحرم ذاك لحِكم، أظهرها الابتلاء بالشكر والصبر. وأخبر أن سنته في الثواب والعقاب الكسب والعمل، فمن أراد الأجر فليعمل بموجباته من الإيمان والعمل الصالح ولا يتمنّاه تمنّياً، ومن خاف العذاب فليكفّ عن الشرك والمعاصي، ومن أراد المال والجاه فليعمل له بسننه، فإن التمنّي بضائع الحمقى: «للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن». ثم بيّن سنّة أخرى في حصول المرغوب، وهي الدعاء: «واسألوا الله من فضله»، فمن سأل ربه وألحّ عليه موقناً بالإجابة أعطاه، فيوفّقه للأسباب ويصرف عنه الموانع، ويعطيه بغير سبب إن شاء. ثم قرّر أن لكلٍّ من الرجال والنساء ورثة يرثونه، أما الموالي بالحلف أو الإخاء فلهم النصرة والرفادة والوصية، إذ لا حظّ لهم في الإرث، والله على كل شيء شهيد، فاتقوه وأطيعوه.", "h": ["قبح التمني وترك العمل.", "حرمة الحسد.", "فضل الدعاء، وأنه من الأسباب التي يحصل بها المراد.", "تقرير مبدأ التوارث في الإسلام.", "من عاقد أحداً على حلف أو آخى أحداً وجب عليه أن يعطيه حق النصرة والمساعدة، وله أن يوصي له بما دون الثلث، أما الإرث فلا حق له فيه لنسخ ذلك.", "وجوب مراقبة الله تعالى؛ لأنه بكل شيء عليم، وعلى كل شيء شهيد."], "k": "ما الذي أتمنّاه مما عند غيري؟ وهل أستبدله اليوم بعمل ودعاء: «واسألوا الله من فضله»؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (70, 4, 34, 42, 'سورة النساء ٣٤ – ٤٢', 'القوامة وإصلاح البيوت، وحقوق العشرة، و«إن الله لا يظلم مثقال ذرة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 70) = $j$[{"lbl": "الآيتان ٣٤ – ٣٥", "q": "ٱلرِّجَالُ قَوَّـٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّـٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّـٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا ﴿٣٤﴾ وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا ﴿٣٥﴾", "w": [["قوّامون", "جمع قوّام، وهو من يقوم على الشيء رعايةً وحمايةً وإصلاحاً."], ["بما فضّل الله بعضهم", "بأن جعل الرجل أكمل في عقله ودينه وبدنه فصلح للقوامة."], ["وبما أنفقوا من أموالهم", "عامل آخر للقوامة؛ فالرجل بدفعه المهر وقيامه بالنفقة أحق بها."], ["الصالحات", "جمع صالحة، وهي المؤدية لحقوق الله تعالى وحقوق زوجها."], ["قانتات", "مطيعات لله ولأزواجهن."], ["حافظات للغيب", "حافظات لفروجهن وأموال أزواجهن."], ["نشوزهن", "النشوز: الترفّع عن الزوج وعدم طاعته."], ["فعظوهن", "بالترغيب في الطاعة والتنفير من المعصية."], ["فلا تبغوا عليهن سبيلاً", "لا تطلبوا طريقاً تتوصّلون به إلى أذيتهن بعد أن أطعنكم."], ["شقاق بينهما", "المنازعة والخصومة حتى يصبح كل واحد في شقّ."], ["حكماً", "الحاكم المحكَّم في القضايا للنظر والحكم فيها."]], "m": "سبب نزولها أن سعد بن الربيع رضي الله عنه أغضبته امرأته فلطمها، فشكاه وليّها إلى رسول الله ﷺ يريد القصاص، فنزلت: «الرجال قوّامون على النساء»، فقال وليّ المرأة: أردنا أمراً وأراد الله غيره، وما أراده الله خير. فالرجل قوّام على المرأة يرعاها ويصلحها بما أوتي من عقل وبُعد نظر، وبما دفع من مهر والتزم من نفقة. ثم أمر الله بإكرام المرأة والإحسان إليها والرفق بها، وأثنى على الصالحات القانتات الحافظات للغيب بحفظ الله لهن. ثم أرشد الأزواج إلى علاج النشوز، وهو ترفّع الزوجة وعدم أدائها حقوق زوجها: يعظها أولاً بتذكيرها بحقه وبعاقبة إضاعته، فإن لم ينفع هجرها في الفراش، فإن أصرّت ضربها ضرباً غير مبرّح لا يشين جارحة ولا يكسر عضواً، فإن أطاعت فلا يحل له أن يطلب طريقاً إلى أذيتها باختلاق الأسباب، إن الله كان علياً كبيراً، فليخشَ الله من أراد أن يعلو على غيره. ثم ذكر حكماً اجتماعياً آخر: إن وقع الشقاق بين الزوجين فلا وفاق بينهما، بُعث حكمٌ من أهله وحكمٌ من أهلها، عدلان عالمان بصيران، يدرسان أسباب الشقاق ويجتهدان في الإصلاح، فإن تعذّر فرّقا بينهما، «إن يريدا إصلاحاً يوفّق الله بينهما»، إن الله كان عليماً خبيراً بنياتهما.", "h": ["تقرير مبدأ القيومية للرجال على النساء، وبخاصة الزوج على زوجته.", "وجوب إكرام الصالحات والإحسان إليهن.", "بيان علاج مشكلة نشوز الزوجة: بوعظها أولاً، ثم هجرانها في الفراش ثانياً، ثم بضربها ثالثاً.", "لا يحل اختلاق الأسباب وإيجاد مبررات لأذية المرأة بضرب أو بغيره.", "مشروعية التحكيم في الشقاق بين الزوجين، وبيان ذلك."], "k": "«إن يريدا إصلاحاً يوفّق الله بينهما»… حين يقع خلاف في بيتي، هل نيتي الإصلاح أم الانتصار؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "۞وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا ﴿٣٦﴾ ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا ﴿٣٧﴾ وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا ﴿٣٨﴾ وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا ﴿٣٩﴾", "w": [["واعبدوا الله", "أطيعوه في أمره ونهيه مع غاية الذل والحب والتعظيم له عز وجل."], ["ولا تشركوا به شيئاً", "لا تعبدوا معه غيره بأي نوع من العبادات، من دعاء وخشية وذبح ونذر وركوع وسجود."], ["ذي القربى", "أصحاب القرابات."], ["والجار ذي القربى", "القريب لنسب أو مصاهرة."], ["والجار الجُنُب", "الأجنبي، مؤمناً كان أو كافراً."], ["والصاحب بالجنب", "الزوجة، والصديق الملازم كالتلميذ والرفيق في السفر."], ["وابن السبيل", "المسافر."], ["وما ملكت أيمانكم", "من الأرقّاء فتيان وفتيات."], ["مختالاً فخوراً", "الاختيال: الزهو في المشي، والفخر: الافتخار بالحسب والنسب والمال بتعداده وذكره."], ["يبخلون", "يمنعون الواجب بذله من المعروف."], ["ويكتمون", "يجحدون ما أعطاهم الله من علم ومال تفضّلاً منه عليهم."], ["قريناً", "الملازم الذي لا يفارق صاحبه."], ["وماذا عليهم", "أي شيء يضرّهم أو ينالهم بمكروه إذا هم آمنوا؟"]], "m": "ما زال السياق في هداية المؤمنين، فأمرهم الله بعبادته وتوحيده فيها، وبالإحسان إلى الوالدين بطاعتهم في المعروف وإسداء الجميل لهم ودفع الأذى عنهم، وكذا الأقرباء واليتامى والمساكين والجيران قريبهم وبعيدهم، والصاحب الملازم كالزوجة ورفيق السفر والعمل والطلب، وابن السبيل وما ملكت اليمين؛ والإحسان إلى هؤلاء آكد، وإلا فالإحسان معروف يُبذل لكل الناس. «إن الله لا يحب من كان مختالاً فخوراً»: دلّ على أن منع الإحسان ناتج عن خُلقي البخل والكبر، وهما من شرّ الأخلاق. ثم ندّد ببخل بعض أهل الكتاب وكتمانهم الحق، فقد كتموا نعوت النبي ﷺ في كتبهم، وبخلوا بأموالهم وأمروا بالبخل، إذ كانوا يقولون للأنصار: لا تنفقوا أموالكم على محمد فإنا نخشى عليكم الفقر، وأعتد الله للكافرين عذاباً مهيناً. ثم ذكر المنافقين الذين ينفقون أموالهم رئاء الناس ولا يؤمنون بالله واليوم الآخر، فالشيطان قرينهم، وساء قريناً. ثم قال موبّخاً وداعياً: «وماذا عليهم لو آمنوا بالله واليوم الآخر وأنفقوا مما رزقهم الله؟»، أي شيء يضرّهم لو صدقوا وأنفقوا؟ وكان الله بهم عليماً، تخويفاً لهم إن استمرّوا على نفاقهم.", "h": ["تقرير عشرة حقوق والأمر بأدائها فوراً، وهي عبادة الله وحده، والإحسان إلى الوالدين وإلى كل المذكورين في الآية الأولى.", "ذم الاختيال الناجم عن الكبر، وذم الفخر، وبيان كره الله تعالى لهما.", "حرمة البخل والأمر به، وحرمة كتمان العلم، وخاصة الشرعي منه.", "حرمة الرياء وذم صاحبه.", "ذم قرناء السوء لما يأمرون به ويدعون إليه قرناءهم."], "k": "من «الجار» و«الصاحب بالجنب» في حياتي؟ وما الإحسان الذي أقدّمه لأحدهم اليوم؟"}, {"lbl": "الآيات ٤٠ – ٤٢", "q": "إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا ﴿٤٠﴾ فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَـٰٓؤُلَآءِ شَهِيدٗا ﴿٤١﴾ يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا ﴿٤٢﴾", "w": [["الظلم", "وضع الشيء في غير موضعه."], ["مثقال ذرة", "المثقال: الوزن، والذرة أصغر حجم، حتى قيل إنه الهباء أو رأس النملة."], ["الحسنة", "الفعلة الجميلة من المعروف."], ["يضاعفها", "يزيد فيها ضعفها."], ["من لدنه", "من عنده."], ["أجراً عظيماً", "جزاءً كبيراً وثواباً عظيماً."], ["الشهيد", "الشاهد على الشيء لعلمه به."], ["تسوّى بهم الأرض", "يكونون تراباً مثلها."], ["ولا يكتمون الله حديثاً", "لا يخفون كلاماً."]], "m": "لما أمر الله بعبادته والإحسان إلى من ذكر، وندّد بالبخل والكبر والفخر وكتمان العلم، وكان ذلك يتطلب الجزاء، ذكر عدله ورحمته في المجازاة: أنه عند الحساب لا يظلم عبده وزن ذرة، فلا ينقص من حسناته حسنة ولا يزيد في سيئاته سيئة، وإن توجد لدى مؤمن حسنة واحدة يضاعفها أضعافاً يعلمها هو، ويؤتِ من عنده أجراً عظيماً لا يُقدر قدره. ثم ذكر هول يوم الحساب، فخاطب رسوله ﷺ: «فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيداً؟»، أي كيف تكون حال أهل الكفر والشر إذا جاء الله بشهيد من كل أمة يشهد عليها فيما أطاعت وعصت، وجيء بالرسول ﷺ شهيداً على أمته أنه بلّغ. يومئذ يودّ الذين كفروا وعصوا الرسول لو يكونون تراباً فلا يُحاسبون، ولا يكتمون الله حديثاً؛ إذ يُختم على أفواههم وتشهد عليهم جوارحهم.", "h": ["بيان عدالة الله تعالى ورحمته ومزيد فضله.", "بيان هول يوم القيامة، حتى إن الكافر ليودّ لو سُوّيت به الأرض فكان تراباً.", "معرفة رسول الله ﷺ بآثار الشهادة على العبد يوم القيامة؛ إذ لما قرأ عليه ابن مسعود رضي الله عنه من أول السورة حتى بلغ «فكيف إذا جئنا من كل أمة بشهيد» قال: «حسبك»، وإذا عيناه تذرفان."], "k": "بكى النبي ﷺ عند هذه الآية… فبماذا سيشهد عليّ يوم القيامة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 70;
insert into public.tdb_cards(topic, i, body) select 70, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٣٤ – ٣٥", "q": "ٱلرِّجَالُ قَوَّـٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّـٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّـٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا ﴿٣٤﴾ وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا ﴿٣٥﴾", "w": [["قوّامون", "جمع قوّام، وهو من يقوم على الشيء رعايةً وحمايةً وإصلاحاً."], ["بما فضّل الله بعضهم", "بأن جعل الرجل أكمل في عقله ودينه وبدنه فصلح للقوامة."], ["وبما أنفقوا من أموالهم", "عامل آخر للقوامة؛ فالرجل بدفعه المهر وقيامه بالنفقة أحق بها."], ["الصالحات", "جمع صالحة، وهي المؤدية لحقوق الله تعالى وحقوق زوجها."], ["قانتات", "مطيعات لله ولأزواجهن."], ["حافظات للغيب", "حافظات لفروجهن وأموال أزواجهن."], ["نشوزهن", "النشوز: الترفّع عن الزوج وعدم طاعته."], ["فعظوهن", "بالترغيب في الطاعة والتنفير من المعصية."], ["فلا تبغوا عليهن سبيلاً", "لا تطلبوا طريقاً تتوصّلون به إلى أذيتهن بعد أن أطعنكم."], ["شقاق بينهما", "المنازعة والخصومة حتى يصبح كل واحد في شقّ."], ["حكماً", "الحاكم المحكَّم في القضايا للنظر والحكم فيها."]], "m": "سبب نزولها أن سعد بن الربيع رضي الله عنه أغضبته امرأته فلطمها، فشكاه وليّها إلى رسول الله ﷺ يريد القصاص، فنزلت: «الرجال قوّامون على النساء»، فقال وليّ المرأة: أردنا أمراً وأراد الله غيره، وما أراده الله خير. فالرجل قوّام على المرأة يرعاها ويصلحها بما أوتي من عقل وبُعد نظر، وبما دفع من مهر والتزم من نفقة. ثم أمر الله بإكرام المرأة والإحسان إليها والرفق بها، وأثنى على الصالحات القانتات الحافظات للغيب بحفظ الله لهن. ثم أرشد الأزواج إلى علاج النشوز، وهو ترفّع الزوجة وعدم أدائها حقوق زوجها: يعظها أولاً بتذكيرها بحقه وبعاقبة إضاعته، فإن لم ينفع هجرها في الفراش، فإن أصرّت ضربها ضرباً غير مبرّح لا يشين جارحة ولا يكسر عضواً، فإن أطاعت فلا يحل له أن يطلب طريقاً إلى أذيتها باختلاق الأسباب، إن الله كان علياً كبيراً، فليخشَ الله من أراد أن يعلو على غيره. ثم ذكر حكماً اجتماعياً آخر: إن وقع الشقاق بين الزوجين فلا وفاق بينهما، بُعث حكمٌ من أهله وحكمٌ من أهلها، عدلان عالمان بصيران، يدرسان أسباب الشقاق ويجتهدان في الإصلاح، فإن تعذّر فرّقا بينهما، «إن يريدا إصلاحاً يوفّق الله بينهما»، إن الله كان عليماً خبيراً بنياتهما.", "h": ["تقرير مبدأ القيومية للرجال على النساء، وبخاصة الزوج على زوجته.", "وجوب إكرام الصالحات والإحسان إليهن.", "بيان علاج مشكلة نشوز الزوجة: بوعظها أولاً، ثم هجرانها في الفراش ثانياً، ثم بضربها ثالثاً.", "لا يحل اختلاق الأسباب وإيجاد مبررات لأذية المرأة بضرب أو بغيره.", "مشروعية التحكيم في الشقاق بين الزوجين، وبيان ذلك."], "k": "«إن يريدا إصلاحاً يوفّق الله بينهما»… حين يقع خلاف في بيتي، هل نيتي الإصلاح أم الانتصار؟"}, {"lbl": "الآيات ٣٦ – ٣٩", "q": "۞وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا ﴿٣٦﴾ ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا ﴿٣٧﴾ وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا ﴿٣٨﴾ وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا ﴿٣٩﴾", "w": [["واعبدوا الله", "أطيعوه في أمره ونهيه مع غاية الذل والحب والتعظيم له عز وجل."], ["ولا تشركوا به شيئاً", "لا تعبدوا معه غيره بأي نوع من العبادات، من دعاء وخشية وذبح ونذر وركوع وسجود."], ["ذي القربى", "أصحاب القرابات."], ["والجار ذي القربى", "القريب لنسب أو مصاهرة."], ["والجار الجُنُب", "الأجنبي، مؤمناً كان أو كافراً."], ["والصاحب بالجنب", "الزوجة، والصديق الملازم كالتلميذ والرفيق في السفر."], ["وابن السبيل", "المسافر."], ["وما ملكت أيمانكم", "من الأرقّاء فتيان وفتيات."], ["مختالاً فخوراً", "الاختيال: الزهو في المشي، والفخر: الافتخار بالحسب والنسب والمال بتعداده وذكره."], ["يبخلون", "يمنعون الواجب بذله من المعروف."], ["ويكتمون", "يجحدون ما أعطاهم الله من علم ومال تفضّلاً منه عليهم."], ["قريناً", "الملازم الذي لا يفارق صاحبه."], ["وماذا عليهم", "أي شيء يضرّهم أو ينالهم بمكروه إذا هم آمنوا؟"]], "m": "ما زال السياق في هداية المؤمنين، فأمرهم الله بعبادته وتوحيده فيها، وبالإحسان إلى الوالدين بطاعتهم في المعروف وإسداء الجميل لهم ودفع الأذى عنهم، وكذا الأقرباء واليتامى والمساكين والجيران قريبهم وبعيدهم، والصاحب الملازم كالزوجة ورفيق السفر والعمل والطلب، وابن السبيل وما ملكت اليمين؛ والإحسان إلى هؤلاء آكد، وإلا فالإحسان معروف يُبذل لكل الناس. «إن الله لا يحب من كان مختالاً فخوراً»: دلّ على أن منع الإحسان ناتج عن خُلقي البخل والكبر، وهما من شرّ الأخلاق. ثم ندّد ببخل بعض أهل الكتاب وكتمانهم الحق، فقد كتموا نعوت النبي ﷺ في كتبهم، وبخلوا بأموالهم وأمروا بالبخل، إذ كانوا يقولون للأنصار: لا تنفقوا أموالكم على محمد فإنا نخشى عليكم الفقر، وأعتد الله للكافرين عذاباً مهيناً. ثم ذكر المنافقين الذين ينفقون أموالهم رئاء الناس ولا يؤمنون بالله واليوم الآخر، فالشيطان قرينهم، وساء قريناً. ثم قال موبّخاً وداعياً: «وماذا عليهم لو آمنوا بالله واليوم الآخر وأنفقوا مما رزقهم الله؟»، أي شيء يضرّهم لو صدقوا وأنفقوا؟ وكان الله بهم عليماً، تخويفاً لهم إن استمرّوا على نفاقهم.", "h": ["تقرير عشرة حقوق والأمر بأدائها فوراً، وهي عبادة الله وحده، والإحسان إلى الوالدين وإلى كل المذكورين في الآية الأولى.", "ذم الاختيال الناجم عن الكبر، وذم الفخر، وبيان كره الله تعالى لهما.", "حرمة البخل والأمر به، وحرمة كتمان العلم، وخاصة الشرعي منه.", "حرمة الرياء وذم صاحبه.", "ذم قرناء السوء لما يأمرون به ويدعون إليه قرناءهم."], "k": "من «الجار» و«الصاحب بالجنب» في حياتي؟ وما الإحسان الذي أقدّمه لأحدهم اليوم؟"}, {"lbl": "الآيات ٤٠ – ٤٢", "q": "إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا ﴿٤٠﴾ فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَـٰٓؤُلَآءِ شَهِيدٗا ﴿٤١﴾ يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا ﴿٤٢﴾", "w": [["الظلم", "وضع الشيء في غير موضعه."], ["مثقال ذرة", "المثقال: الوزن، والذرة أصغر حجم، حتى قيل إنه الهباء أو رأس النملة."], ["الحسنة", "الفعلة الجميلة من المعروف."], ["يضاعفها", "يزيد فيها ضعفها."], ["من لدنه", "من عنده."], ["أجراً عظيماً", "جزاءً كبيراً وثواباً عظيماً."], ["الشهيد", "الشاهد على الشيء لعلمه به."], ["تسوّى بهم الأرض", "يكونون تراباً مثلها."], ["ولا يكتمون الله حديثاً", "لا يخفون كلاماً."]], "m": "لما أمر الله بعبادته والإحسان إلى من ذكر، وندّد بالبخل والكبر والفخر وكتمان العلم، وكان ذلك يتطلب الجزاء، ذكر عدله ورحمته في المجازاة: أنه عند الحساب لا يظلم عبده وزن ذرة، فلا ينقص من حسناته حسنة ولا يزيد في سيئاته سيئة، وإن توجد لدى مؤمن حسنة واحدة يضاعفها أضعافاً يعلمها هو، ويؤتِ من عنده أجراً عظيماً لا يُقدر قدره. ثم ذكر هول يوم الحساب، فخاطب رسوله ﷺ: «فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيداً؟»، أي كيف تكون حال أهل الكفر والشر إذا جاء الله بشهيد من كل أمة يشهد عليها فيما أطاعت وعصت، وجيء بالرسول ﷺ شهيداً على أمته أنه بلّغ. يومئذ يودّ الذين كفروا وعصوا الرسول لو يكونون تراباً فلا يُحاسبون، ولا يكتمون الله حديثاً؛ إذ يُختم على أفواههم وتشهد عليهم جوارحهم.", "h": ["بيان عدالة الله تعالى ورحمته ومزيد فضله.", "بيان هول يوم القيامة، حتى إن الكافر ليودّ لو سُوّيت به الأرض فكان تراباً.", "معرفة رسول الله ﷺ بآثار الشهادة على العبد يوم القيامة؛ إذ لما قرأ عليه ابن مسعود رضي الله عنه من أول السورة حتى بلغ «فكيف إذا جئنا من كل أمة بشهيد» قال: «حسبك»، وإذا عيناه تذرفان."], "k": "بكى النبي ﷺ عند هذه الآية… فبماذا سيشهد عليّ يوم القيامة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (71, 4, 43, 55, 'سورة النساء ٤٣ – ٥٥', 'لا تقربوا الصلاة وأنتم سكارى، والتيمم، والشرك لا يُغفر', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 71) = $j$[{"lbl": "الآية ٤٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا ﴿٤٣﴾", "w": [["لا تقربوا الصلاة", "لا تدخلوا فيها، أو لا تدنوا من مساجدها."], ["سكارى", "جمع سكران، وهو من شرب مسكراً فستر عقله وغطّاه."], ["حتى تعلموا ما تقولون", "لزوال السكر عنكم، وهذا كان قبل تحريم الخمر."], ["ولا جُنُباً", "الجنب: من به جنابة، ولها سببان: جماع أو احتلام."], ["عابري سبيل", "مارّين بالمسجد مروراً دون جلوس فيه."], ["الغائط", "المكان المنخفض للتبرّز فيه."], ["لامستم النساء", "جامعتموهن."], ["فتيمموا صعيداً طيباً", "اقصدوا تراباً طاهراً."], ["عفوّاً غفوراً", "عفوّاً لا يؤاخذ على كل ذنب، غفوراً كثير المغفرة لذنوب عباده التائبين."]], "m": "سبب نزولها، حسب رواية الترمذي، أن عبد الرحمن بن عوف رضي الله عنه أقام مأدبة لبعض الأصحاب فأكلوا وشربوا، وكانت الخمر يومئذ حلالاً، وحضرت الصلاة فتقدّم أحدهم يصلي بهم وهو ثمل، فقرأ «قل يا أيها الكافرون» بحذف حروف النفي فاختلّ المعنى، فنزلت: لا تدخلوا في الصلاة وأنتم سكارى حتى تكون عقولكم تامة فتعلموا ما تقولون، ولا تقربوا مساجد الصلاة للجلوس فيها وأنتم جنب حتى تغتسلوا، إلا عابري سبيل، إذ كانت طرق بعضهم إلى منازلهم تمر بالمسجد النبوي. وإن كنتم مرضى لا تقدرون معه على استعمال الماء، أو على سفر، أو جاء أحد منكم من الغائط، أو لامستم النساء، فلم تجدوا ماءً للغسل أو الوضوء، فاقصدوا تراباً طاهراً فامسحوا بوجوهكم وأيديكم، فإن ذلك مجزئ عن الغسل والوضوء، فإذا صحّ المريض أو وُجد الماء فلا تيمّم لانتفاء الرخصة. إن الله كان عفوّاً غفوراً، ولذا لم يؤاخذهم لما صلّوا وهم سكارى، وأنزل القرآن تعليماً لهم وهداية.", "h": ["تقرير مبدأ النسخ للأحكام الشرعية في القرآن والسنة.", "حرمة مكث الجنب في المسجد، وجواز العبور والاجتياز بدون مكث.", "وجوب الغسل على الجنب، وهو من احتلم فرأى الماء أو جامع ولو لم يُنزل.", "إذا لم يجد المرء التراب لمطر ونحوه تيمّم بكل أجزاء الأرض من رمل وسبخة وحجارة، والتيمم أن يضرب بكفّيه الأرض ثم يمسح وجهه وكفّيه بهما، لحديث عمّار رضي الله عنه في الصحيح.", "بيان عفو الله وغفرانه، لعدم مؤاخذة من صلّوا وهم سكارى."], "k": "«حتى تعلموا ما تقولون»… كم صلاة صلّيتها ولم أعلم ما أقول فيها؟"}, {"lbl": "الآيات ٤٤ – ٤٦", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ ﴿٤٤﴾ وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا ﴿٤٥﴾ مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا ﴿٤٦﴾", "w": [["ألم ترَ", "ألم تبصر بقلبك، أي تعلم."], ["نصيباً", "حظاً وقسطاً."], ["يشترون الضلالة", "الكفر بالإيمان."], ["الأعداء", "جمع عدو، وهو من يودّ ضرّك ويكره نفعك."], ["هادوا", "اليهود، قيل لهم ذلك لقولهم: «إنا هُدنا إليك»، أي تبنا ورجعنا."], ["يحرّفون", "التحريف: الميل بالكلام عن معناه إلى معنى باطل للتضليل."], ["الكلم", "كلام الله تعالى في التوراة."], ["واسمع غير مُسمَع", "اسمع ما تقول، لا أسمعك الله، وهذا كفر منهم صريح."], ["وطعناً في الدين", "سبّهم للرسول ﷺ هو الطعن الأعظم في الدين."], ["وانظرنا", "أمهلنا حتى نسمع فنفهم."], ["أقوم", "أعدل وأصوب."], ["لعنهم الله بكفرهم", "طردهم من رحمته وأبعدهم من هداه بسبب كفرهم برسول الله ﷺ."]], "m": "رُوي أنها نزلت في رفاعة بن زيد بن التابوت، أحد عظماء اليهود بالمدينة، كان إذا كلّم رسول الله ﷺ لوى لسانه وقال: راعنا سمعك يا محمد، ثم طعن في الإسلام. فقال الله: ألم ينتهِ إلى علمك أمرٌ يدعو إلى العجب: الذين أوتوا حظاً من التوراة فعرفوا صحة الإسلام وصدق نبيه، يشترون الكفر بالإيمان حيث جحدوا نعوت النبي ﷺ في التوراة إبقاءً على رئاستهم، ويريدون أن تضلّوا أيها المؤمنون سبيل الحق. والله أعلم بأعدائكم، فأخبركم بهم لتجتنبوهم، وكفى بالله ولياً تعتمدون عليه، وكفى بالله نصيراً. من اليهود من يحرّفون كلام الله في التوراة عن مواضعه بالتأويل الباطل أو التبديل، ويقولون للنبي ﷺ كفراً وعناداً: سمعنا وعصينا، واسمع غير مُسمَع، وراعنا، وهي كلمة ظاهرها المراعاة وباطنها السبّ، يلوون بها ألسنتهم طعناً في الدين. ولو أنهم قالوا: سمعنا وأطعنا، واسمع وانظرنا، لكان خيراً لهم وأقوم، ولكن لعنهم الله بكفرهم فلا يؤمنون إلا قليلاً لا ينفعهم.", "h": ["بيان مكر اليهود بالمؤمنين بالعمل على إضلالهم، في عهد النبوة وإلى اليوم.", "في كفاية الله المؤمنين ونصرته ما يغنيهم أن يطلبوا ذلك من أحد غير ربهم عز وجل.", "الكشف عن سوء نيات اليهود وأعمالهم إزاء رسول الله ﷺ.", "الإيمان القليل لا يجدي صاحبه ولا ينفعه بحال."], "k": "«سمعنا وأطعنا»… هل هي جوابي حين يبلغني أمر من الله ورسوله؟"}, {"lbl": "الآية ٤٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا ﴿٤٧﴾", "w": [["أوتوا الكتاب", "المراد بهم هنا اليهود."], ["بما نزّلنا مصدّقاً", "القرآن."], ["نطمس وجوهاً", "نُذهب آثارها بطمس الأعين وإذهاب أحداقها."], ["فنردّها على أدبارها", "نجعل الوجه قفاً والقفا وجهاً."], ["كما لعنّا أصحاب السبت", "لعنهم: مسخهم قردة خزياً لهم."], ["وكان أمر الله مفعولاً", "مأموره كائن لا محالة، لأنه تعالى لا يعجزه شيء."]], "m": "ما زال السياق في اليهود المجاورين للرسول ﷺ بالمدينة، فناداهم الله بعنوان العلم، إذ هم أهل كتاب، وأمرهم بالإيمان بالقرآن المصدّق لما معهم من أصول الدين ونعوت الرسول، وبمن أُنزل عليه ﷺ، وأن يتركوا التردد من قبل أن يحلّ بهم ما حلّ ببعض أسلافهم: من قبل أن نطمس وجوهاً فنذهب أعينها وشاخص أنوفها، فتصبح الوجوه أقفاءً يمشون القهقرى، أو نلعنهم كما لعنّا الذين اعتدوا في السبت فمسخناهم قردة، وكان أمر الله مفعولاً ناجزاً لا يتخلّف.", "h": ["المفروض أن ذا العلم أقرب إلى الهداية، ولكن من سبقت شقوته لاختياره الشر وإصراره عليه لا ينفعه العلم، كهؤلاء اليهود الذين دعاهم الله إلى الإيمان فلم يؤمنوا.", "وجوب تعجيل التوبة قبل نزول العذاب وحلول ما لا يحب الإنسان.", "قد يكون المسخ في الوجوه بمسخ الأفكار والعقول، فتفسد حياة المرء وتسوء، وهذا الذي حصل ليهود المدينة، فنقضوا عهودهم فهلك من هلك وأُجلي من أُجلي."], "k": "العلم وحده لا يكفي… فهل يزيدني ما أتعلّمه من القرآن قرباً وعملاً؟"}, {"lbl": "الآية ٤٨", "q": "إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا ﴿٤٨﴾", "w": [["لا يغفر", "لا يمحو ولا يترك المؤاخذة."], ["أن يُشرك به", "أن يُعبد معه غيره، بحبه وتعظيمه وصرف العبادات له كدعائه والاستعانة به والذبح والنذر له."], ["ويغفر ما دون ذلك", "ما دون الشرك والكفر من سائر الذنوب والمعاصي."], ["لمن يشاء", "لمن يشاء المغفرة له من المذنبين بغير الشرك والكفر."], ["افترى إثماً عظيماً", "اختلق وكذب بنسبته العبادة إلى غير الرب تعالى، والإثم: الذنب العظيم."]], "m": "يُروى أنه لما نزل قول الله في سورة الزمر: «قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله إن الله يغفر الذنوب جميعاً»، قام رجل فقال: والشرك يا نبي الله؟ فكره ذلك رسول الله ﷺ، وأنزل الله: «إن الله لا يغفر أن يُشرك به ويغفر ما دون ذلك لمن يشاء»؛ فأخبر أنه لا يغفر ذنب الشرك والكفر، وأما سائر الذنوب كبيرها وصغيرها فتحت المشيئة، إن شاء غفرها، وإن شاء أخذ بها. ومن يشرك بالله فقد اختلق الكذب العظيم؛ إذ عبد من لا يستحق العبادة وألّه من لا حق له في التأليه، فهو قائل بالزور عامل بالباطل، ومن هنا كان ذنبه عظيماً.", "h": ["عظم ذنب الشرك والكفر، وأن كل الذنوب دونهما.", "الشرك ذنب لا يُغفر لمن مات بدون توبة منه.", "سائر الذنوب دون الشرك والكفر لا ييأس فاعلها من مغفرة الله له، وإنما يخاف.", "الشرك زور، وفاعله قائل بالزور فاعلٌ به."], "k": "هل في قلبي تعلّق بغير الله: خوفاً أو رجاءً أو اعتماداً؟"}, {"lbl": "الآيتان ٤٩ – ٥٠", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا ﴿٤٩﴾ ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا ﴿٥٠﴾", "w": [["تزكية النفس", "تبرئتها من الذنوب والآثام."], ["يزكّي من يشاء", "يطهّر من الذنوب من يشاء من عباده بتوفيقه للعمل بما يزكّي النفس."], ["فتيلاً", "الخيط الأبيض في وسط النواة، أو ما يفتله المرء بإصبعيه من الوسخ، وهو أقل الأشياء."], ["الكذب", "عدم مطابقة الخبر للواقع."]], "m": "عاد السياق إلى أهل الكتاب، فقال تعالى: «ألم تر إلى الذين يزكّون أنفسهم»، وهو أمر يدعو إلى العجب؛ إذ المفروض ألا يزكّي المرء نفسه حتى يزكّيه غيره. فاليهود والنصارى قالوا: نحن أبناء الله وأحباؤه، وقالوا: لن يدخل الجنة إلا من كان هوداً أو نصارى، وقالت اليهود: لن تمسّنا النار إلا أياماً معدودات، إلى غير ذلك من الدعاوى الباطلة التي عاقتهم عن الإيمان. فأنكر الله ذلك، وأخبر أنه هو الذي يزكّي من يشاء بتوفيقه إلى الإيمان وصالح الأعمال، ولا يُظلمون فتيلاً، فلا يُزاد في ذنوب العبد ولا يُنقص من حسناته. ثم أمر رسوله ﷺ أن يتعجّب من كذبهم على الله بتلك الدعاوى، وكفى بالكذب إثماً مبيناً.", "h": ["حرمة تزكية المرء نفسه بلسانه والتفاخر بذلك، إما طلباً للرئاسة، وإما تخلّياً عن العبادة بحجة أنه في غير حاجة إليها.", "الله يزكّي عبده بالثناء عليه في الملأ الأعلى، وبتوفيقه للعمل بما يزكّي النفس من صلاة وصدقة وسائر الطاعات.", "عدالة الحساب والجزاء يوم القيامة، لقوله تعالى: «ولا يُظلمون فتيلاً»."], "k": "هل أرى نفسي أفضل من غيري؟ ومتى آخر مرة اتهمتُ نفسي بالتقصير؟"}, {"lbl": "الآيات ٥١ – ٥٥", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَـٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا ﴿٥١﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا ﴿٥٢﴾ أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا ﴿٥٣﴾ أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا ﴿٥٤﴾ فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا ﴿٥٥﴾", "w": [["الجبت والطاغوت", "الجبت: اسم لكل ما عُبد من دون الله، وكذا الطاغوت، سواء كانا صنمين أو رجلين."], ["أهدى سبيلاً", "أكثر هداية في حياتها وسلوكها."], ["نقيراً", "النقير: نقرة في ظهر النواة، يُضرب بها المثل في الصغر."], ["آل إبراهيم", "ذريته من أولاد وأحفاد، كداود وسليمان ومن بعدهم."]], "m": "رُوي أن جماعة من اليهود، منهم كعب بن الأشرف وحُيي بن أخطب، ذهبوا إلى مكة يحزّبون الأحزاب لحرب رسول الله ﷺ، فقالت قريش: نسألهم فإنهم أهل كتاب: أديننا خير أم دين محمد؟ فقالوا: دينكم خير وأنتم أهدى منه وممن اتبعه، فنزلت: ألم ينتهِ إلى علمك أن الذين أوتوا حظاً من التوراة يصدّقون بعبادة الجبت والطاغوت ويفضّلونها على عبادة الله، ويقولون لمشركي قريش: أنتم أهدى من الذين آمنوا سبيلاً؟ أولئك لعنهم الله فأبعدهم عن الخير والهدى، ومن يلعن الله فلن تجد له نصيراً. ثم أنكر دعواهم أن الملك سيؤول إليهم، وهم لشدة بخلهم لو آل إليهم ما أعطوا الناس نقيراً، فذمّهم بالبخل بعد ذمّهم بالجهل. ثم أنكر حسدهم للنبي ﷺ والمؤمنين على النبوة والدولة، وقد آتى الله آل إبراهيم الكتاب والحكمة وملكاً عظيماً كملك داود وسليمان ﵉، وهم يعرفون ذلك ولا يحسدونهم. فمن اليهود من آمن به وهم القليل، ومنهم من صدّ عنه وهم الأكثرون، وكفى بجهنم سعيراً لمن كفر حسداً وصدّ عن سبيل الله.", "h": ["وجوب الكفر بالجبت والطاغوت.", "بيان مكر اليهود وغشّهم، وأنهم لا يتورّعون عن الغش والكذب والتضليل.", "ذم الحسد والبخل.", "إيمان بعض اليهود بالإسلام، وكفر أكثرهم مع علمهم بصحة الإسلام ووجوب الإيمان به والدخول فيه."], "k": "«أم يحسدون الناس على ما آتاهم الله من فضله»… هل أفرح بنعمة غيري، أم يضيق بها صدري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 71;
insert into public.tdb_cards(topic, i, body) select 71, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ٤٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا ﴿٤٣﴾", "w": [["لا تقربوا الصلاة", "لا تدخلوا فيها، أو لا تدنوا من مساجدها."], ["سكارى", "جمع سكران، وهو من شرب مسكراً فستر عقله وغطّاه."], ["حتى تعلموا ما تقولون", "لزوال السكر عنكم، وهذا كان قبل تحريم الخمر."], ["ولا جُنُباً", "الجنب: من به جنابة، ولها سببان: جماع أو احتلام."], ["عابري سبيل", "مارّين بالمسجد مروراً دون جلوس فيه."], ["الغائط", "المكان المنخفض للتبرّز فيه."], ["لامستم النساء", "جامعتموهن."], ["فتيمموا صعيداً طيباً", "اقصدوا تراباً طاهراً."], ["عفوّاً غفوراً", "عفوّاً لا يؤاخذ على كل ذنب، غفوراً كثير المغفرة لذنوب عباده التائبين."]], "m": "سبب نزولها، حسب رواية الترمذي، أن عبد الرحمن بن عوف رضي الله عنه أقام مأدبة لبعض الأصحاب فأكلوا وشربوا، وكانت الخمر يومئذ حلالاً، وحضرت الصلاة فتقدّم أحدهم يصلي بهم وهو ثمل، فقرأ «قل يا أيها الكافرون» بحذف حروف النفي فاختلّ المعنى، فنزلت: لا تدخلوا في الصلاة وأنتم سكارى حتى تكون عقولكم تامة فتعلموا ما تقولون، ولا تقربوا مساجد الصلاة للجلوس فيها وأنتم جنب حتى تغتسلوا، إلا عابري سبيل، إذ كانت طرق بعضهم إلى منازلهم تمر بالمسجد النبوي. وإن كنتم مرضى لا تقدرون معه على استعمال الماء، أو على سفر، أو جاء أحد منكم من الغائط، أو لامستم النساء، فلم تجدوا ماءً للغسل أو الوضوء، فاقصدوا تراباً طاهراً فامسحوا بوجوهكم وأيديكم، فإن ذلك مجزئ عن الغسل والوضوء، فإذا صحّ المريض أو وُجد الماء فلا تيمّم لانتفاء الرخصة. إن الله كان عفوّاً غفوراً، ولذا لم يؤاخذهم لما صلّوا وهم سكارى، وأنزل القرآن تعليماً لهم وهداية.", "h": ["تقرير مبدأ النسخ للأحكام الشرعية في القرآن والسنة.", "حرمة مكث الجنب في المسجد، وجواز العبور والاجتياز بدون مكث.", "وجوب الغسل على الجنب، وهو من احتلم فرأى الماء أو جامع ولو لم يُنزل.", "إذا لم يجد المرء التراب لمطر ونحوه تيمّم بكل أجزاء الأرض من رمل وسبخة وحجارة، والتيمم أن يضرب بكفّيه الأرض ثم يمسح وجهه وكفّيه بهما، لحديث عمّار رضي الله عنه في الصحيح.", "بيان عفو الله وغفرانه، لعدم مؤاخذة من صلّوا وهم سكارى."], "k": "«حتى تعلموا ما تقولون»… كم صلاة صلّيتها ولم أعلم ما أقول فيها؟"}, {"lbl": "الآيات ٤٤ – ٤٦", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ ﴿٤٤﴾ وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا ﴿٤٥﴾ مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا ﴿٤٦﴾", "w": [["ألم ترَ", "ألم تبصر بقلبك، أي تعلم."], ["نصيباً", "حظاً وقسطاً."], ["يشترون الضلالة", "الكفر بالإيمان."], ["الأعداء", "جمع عدو، وهو من يودّ ضرّك ويكره نفعك."], ["هادوا", "اليهود، قيل لهم ذلك لقولهم: «إنا هُدنا إليك»، أي تبنا ورجعنا."], ["يحرّفون", "التحريف: الميل بالكلام عن معناه إلى معنى باطل للتضليل."], ["الكلم", "كلام الله تعالى في التوراة."], ["واسمع غير مُسمَع", "اسمع ما تقول، لا أسمعك الله، وهذا كفر منهم صريح."], ["وطعناً في الدين", "سبّهم للرسول ﷺ هو الطعن الأعظم في الدين."], ["وانظرنا", "أمهلنا حتى نسمع فنفهم."], ["أقوم", "أعدل وأصوب."], ["لعنهم الله بكفرهم", "طردهم من رحمته وأبعدهم من هداه بسبب كفرهم برسول الله ﷺ."]], "m": "رُوي أنها نزلت في رفاعة بن زيد بن التابوت، أحد عظماء اليهود بالمدينة، كان إذا كلّم رسول الله ﷺ لوى لسانه وقال: راعنا سمعك يا محمد، ثم طعن في الإسلام. فقال الله: ألم ينتهِ إلى علمك أمرٌ يدعو إلى العجب: الذين أوتوا حظاً من التوراة فعرفوا صحة الإسلام وصدق نبيه، يشترون الكفر بالإيمان حيث جحدوا نعوت النبي ﷺ في التوراة إبقاءً على رئاستهم، ويريدون أن تضلّوا أيها المؤمنون سبيل الحق. والله أعلم بأعدائكم، فأخبركم بهم لتجتنبوهم، وكفى بالله ولياً تعتمدون عليه، وكفى بالله نصيراً. من اليهود من يحرّفون كلام الله في التوراة عن مواضعه بالتأويل الباطل أو التبديل، ويقولون للنبي ﷺ كفراً وعناداً: سمعنا وعصينا، واسمع غير مُسمَع، وراعنا، وهي كلمة ظاهرها المراعاة وباطنها السبّ، يلوون بها ألسنتهم طعناً في الدين. ولو أنهم قالوا: سمعنا وأطعنا، واسمع وانظرنا، لكان خيراً لهم وأقوم، ولكن لعنهم الله بكفرهم فلا يؤمنون إلا قليلاً لا ينفعهم.", "h": ["بيان مكر اليهود بالمؤمنين بالعمل على إضلالهم، في عهد النبوة وإلى اليوم.", "في كفاية الله المؤمنين ونصرته ما يغنيهم أن يطلبوا ذلك من أحد غير ربهم عز وجل.", "الكشف عن سوء نيات اليهود وأعمالهم إزاء رسول الله ﷺ.", "الإيمان القليل لا يجدي صاحبه ولا ينفعه بحال."], "k": "«سمعنا وأطعنا»… هل هي جوابي حين يبلغني أمر من الله ورسوله؟"}, {"lbl": "الآية ٤٧", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا ﴿٤٧﴾", "w": [["أوتوا الكتاب", "المراد بهم هنا اليهود."], ["بما نزّلنا مصدّقاً", "القرآن."], ["نطمس وجوهاً", "نُذهب آثارها بطمس الأعين وإذهاب أحداقها."], ["فنردّها على أدبارها", "نجعل الوجه قفاً والقفا وجهاً."], ["كما لعنّا أصحاب السبت", "لعنهم: مسخهم قردة خزياً لهم."], ["وكان أمر الله مفعولاً", "مأموره كائن لا محالة، لأنه تعالى لا يعجزه شيء."]], "m": "ما زال السياق في اليهود المجاورين للرسول ﷺ بالمدينة، فناداهم الله بعنوان العلم، إذ هم أهل كتاب، وأمرهم بالإيمان بالقرآن المصدّق لما معهم من أصول الدين ونعوت الرسول، وبمن أُنزل عليه ﷺ، وأن يتركوا التردد من قبل أن يحلّ بهم ما حلّ ببعض أسلافهم: من قبل أن نطمس وجوهاً فنذهب أعينها وشاخص أنوفها، فتصبح الوجوه أقفاءً يمشون القهقرى، أو نلعنهم كما لعنّا الذين اعتدوا في السبت فمسخناهم قردة، وكان أمر الله مفعولاً ناجزاً لا يتخلّف.", "h": ["المفروض أن ذا العلم أقرب إلى الهداية، ولكن من سبقت شقوته لاختياره الشر وإصراره عليه لا ينفعه العلم، كهؤلاء اليهود الذين دعاهم الله إلى الإيمان فلم يؤمنوا.", "وجوب تعجيل التوبة قبل نزول العذاب وحلول ما لا يحب الإنسان.", "قد يكون المسخ في الوجوه بمسخ الأفكار والعقول، فتفسد حياة المرء وتسوء، وهذا الذي حصل ليهود المدينة، فنقضوا عهودهم فهلك من هلك وأُجلي من أُجلي."], "k": "العلم وحده لا يكفي… فهل يزيدني ما أتعلّمه من القرآن قرباً وعملاً؟"}, {"lbl": "الآية ٤٨", "q": "إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا ﴿٤٨﴾", "w": [["لا يغفر", "لا يمحو ولا يترك المؤاخذة."], ["أن يُشرك به", "أن يُعبد معه غيره، بحبه وتعظيمه وصرف العبادات له كدعائه والاستعانة به والذبح والنذر له."], ["ويغفر ما دون ذلك", "ما دون الشرك والكفر من سائر الذنوب والمعاصي."], ["لمن يشاء", "لمن يشاء المغفرة له من المذنبين بغير الشرك والكفر."], ["افترى إثماً عظيماً", "اختلق وكذب بنسبته العبادة إلى غير الرب تعالى، والإثم: الذنب العظيم."]], "m": "يُروى أنه لما نزل قول الله في سورة الزمر: «قل يا عبادي الذين أسرفوا على أنفسهم لا تقنطوا من رحمة الله إن الله يغفر الذنوب جميعاً»، قام رجل فقال: والشرك يا نبي الله؟ فكره ذلك رسول الله ﷺ، وأنزل الله: «إن الله لا يغفر أن يُشرك به ويغفر ما دون ذلك لمن يشاء»؛ فأخبر أنه لا يغفر ذنب الشرك والكفر، وأما سائر الذنوب كبيرها وصغيرها فتحت المشيئة، إن شاء غفرها، وإن شاء أخذ بها. ومن يشرك بالله فقد اختلق الكذب العظيم؛ إذ عبد من لا يستحق العبادة وألّه من لا حق له في التأليه، فهو قائل بالزور عامل بالباطل، ومن هنا كان ذنبه عظيماً.", "h": ["عظم ذنب الشرك والكفر، وأن كل الذنوب دونهما.", "الشرك ذنب لا يُغفر لمن مات بدون توبة منه.", "سائر الذنوب دون الشرك والكفر لا ييأس فاعلها من مغفرة الله له، وإنما يخاف.", "الشرك زور، وفاعله قائل بالزور فاعلٌ به."], "k": "هل في قلبي تعلّق بغير الله: خوفاً أو رجاءً أو اعتماداً؟"}, {"lbl": "الآيتان ٤٩ – ٥٠", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا ﴿٤٩﴾ ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا ﴿٥٠﴾", "w": [["تزكية النفس", "تبرئتها من الذنوب والآثام."], ["يزكّي من يشاء", "يطهّر من الذنوب من يشاء من عباده بتوفيقه للعمل بما يزكّي النفس."], ["فتيلاً", "الخيط الأبيض في وسط النواة، أو ما يفتله المرء بإصبعيه من الوسخ، وهو أقل الأشياء."], ["الكذب", "عدم مطابقة الخبر للواقع."]], "m": "عاد السياق إلى أهل الكتاب، فقال تعالى: «ألم تر إلى الذين يزكّون أنفسهم»، وهو أمر يدعو إلى العجب؛ إذ المفروض ألا يزكّي المرء نفسه حتى يزكّيه غيره. فاليهود والنصارى قالوا: نحن أبناء الله وأحباؤه، وقالوا: لن يدخل الجنة إلا من كان هوداً أو نصارى، وقالت اليهود: لن تمسّنا النار إلا أياماً معدودات، إلى غير ذلك من الدعاوى الباطلة التي عاقتهم عن الإيمان. فأنكر الله ذلك، وأخبر أنه هو الذي يزكّي من يشاء بتوفيقه إلى الإيمان وصالح الأعمال، ولا يُظلمون فتيلاً، فلا يُزاد في ذنوب العبد ولا يُنقص من حسناته. ثم أمر رسوله ﷺ أن يتعجّب من كذبهم على الله بتلك الدعاوى، وكفى بالكذب إثماً مبيناً.", "h": ["حرمة تزكية المرء نفسه بلسانه والتفاخر بذلك، إما طلباً للرئاسة، وإما تخلّياً عن العبادة بحجة أنه في غير حاجة إليها.", "الله يزكّي عبده بالثناء عليه في الملأ الأعلى، وبتوفيقه للعمل بما يزكّي النفس من صلاة وصدقة وسائر الطاعات.", "عدالة الحساب والجزاء يوم القيامة، لقوله تعالى: «ولا يُظلمون فتيلاً»."], "k": "هل أرى نفسي أفضل من غيري؟ ومتى آخر مرة اتهمتُ نفسي بالتقصير؟"}, {"lbl": "الآيات ٥١ – ٥٥", "q": "أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَـٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا ﴿٥١﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا ﴿٥٢﴾ أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا ﴿٥٣﴾ أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا ﴿٥٤﴾ فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا ﴿٥٥﴾", "w": [["الجبت والطاغوت", "الجبت: اسم لكل ما عُبد من دون الله، وكذا الطاغوت، سواء كانا صنمين أو رجلين."], ["أهدى سبيلاً", "أكثر هداية في حياتها وسلوكها."], ["نقيراً", "النقير: نقرة في ظهر النواة، يُضرب بها المثل في الصغر."], ["آل إبراهيم", "ذريته من أولاد وأحفاد، كداود وسليمان ومن بعدهم."]], "m": "رُوي أن جماعة من اليهود، منهم كعب بن الأشرف وحُيي بن أخطب، ذهبوا إلى مكة يحزّبون الأحزاب لحرب رسول الله ﷺ، فقالت قريش: نسألهم فإنهم أهل كتاب: أديننا خير أم دين محمد؟ فقالوا: دينكم خير وأنتم أهدى منه وممن اتبعه، فنزلت: ألم ينتهِ إلى علمك أن الذين أوتوا حظاً من التوراة يصدّقون بعبادة الجبت والطاغوت ويفضّلونها على عبادة الله، ويقولون لمشركي قريش: أنتم أهدى من الذين آمنوا سبيلاً؟ أولئك لعنهم الله فأبعدهم عن الخير والهدى، ومن يلعن الله فلن تجد له نصيراً. ثم أنكر دعواهم أن الملك سيؤول إليهم، وهم لشدة بخلهم لو آل إليهم ما أعطوا الناس نقيراً، فذمّهم بالبخل بعد ذمّهم بالجهل. ثم أنكر حسدهم للنبي ﷺ والمؤمنين على النبوة والدولة، وقد آتى الله آل إبراهيم الكتاب والحكمة وملكاً عظيماً كملك داود وسليمان ﵉، وهم يعرفون ذلك ولا يحسدونهم. فمن اليهود من آمن به وهم القليل، ومنهم من صدّ عنه وهم الأكثرون، وكفى بجهنم سعيراً لمن كفر حسداً وصدّ عن سبيل الله.", "h": ["وجوب الكفر بالجبت والطاغوت.", "بيان مكر اليهود وغشّهم، وأنهم لا يتورّعون عن الغش والكذب والتضليل.", "ذم الحسد والبخل.", "إيمان بعض اليهود بالإسلام، وكفر أكثرهم مع علمهم بصحة الإسلام ووجوب الإيمان به والدخول فيه."], "k": "«أم يحسدون الناس على ما آتاهم الله من فضله»… هل أفرح بنعمة غيري، أم يضيق بها صدري؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;